//! File-type icon lookup tables.
//!
//! Generated by `scripts/gen-icon-map.py` from a VS Code icon-theme JSON. Do
//! not edit by hand: rerun the script instead. Every name here is the stem of
//! a file under `assets/icons/file/`, which `build.rs` packs into the binary.
//!
//! Each table is sorted by key so the lookups can binary search.

// ========================================================================
// Constants
// ========================================================================

/// Drawn for a file no table matches.
pub(crate) static DEFAULT_FILE: &str = "default_file";

/// Drawn for a collapsed directory no table matches.
pub(crate) static DEFAULT_FOLDER: &str = "default_folder";

/// Drawn for an expanded directory no table matches.
pub(crate) static DEFAULT_FOLDER_OPEN: &str = "default_folder_opened";

